import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event Data Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Configure ingestion pipeline with optimized table ordering
// Ordered by user_id and event_ts for efficient date-range queries by user
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts", "action"]
  },
  stream: true,
  ingestApi: true,
});

